package com.yourname.blog.Blog.service;
import com.yourname.blog.Blog.dto.ArticleResponse; import com.yourname.blog.Blog.entity.*; import com.yourname.blog.Blog.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Service;
@Service @RequiredArgsConstructor public class ArticleMapper { private final LikeRepository likes; private final CommentRepository comments; private final BookmarkRepository bookmarks; private final UserRepository users;
 public ArticleResponse map(Blog b){int minutes=Math.max(1,(b.getContent().trim().split("\\s+").length+199)/200);String text=b.getContent();String excerpt=text.length()>180?text.substring(0,180)+"…":text;boolean liked=false,saved=false;var a=SecurityContextHolder.getContext().getAuthentication();if(a!=null&&a.isAuthenticated()){var u=users.findByEmail(a.getName());if(u.isPresent()){liked=likes.findByBlogAndUser(b,u.get()).isPresent();saved=bookmarks.findByBlogAndUser(b,u.get()).isPresent();}}return new ArticleResponse(b.getId(),b.getTitle(),text,excerpt,b.getCreatedAt(),b.getAuthor().getName(),b.getAuthor().getId(),likes.countByBlog(b),comments.countByBlog(b),minutes,liked,saved);}
}
